#include <bits/stdc++.h>
using namespace std;

int main() {
    int w = 0, x = 0, y = 0, z = 0, num = 0;
    char c;

    while (scanf("%c", &c) == 1) {
        ++num;
        if (num >= 5) w = 1;
        if (isdigit(static_cast<unsigned char>(c))) x = 1;
        if (c >= 'A' && c <= 'Z') y = 1;
        if (c >= 'a' && c <= 'z') z = 1;

        if (w && x && y && z)
            return printf("Correct"), 0;
    }

    return printf("Too weak"), 0;
}

